import * as cheerio from 'cheerio';

/**
 * Escape a value for safe use inside a double-quoted HTML attribute.
 */
export function escapeAttr(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

/**
 * Truncate a description to at most 155 characters on a word boundary.
 * Never leaves a dangling trailing comma or space.
 */
export function truncateDescription(text, max = 155) {
  const str = String(text ?? '');
  if (str.length <= max) return str;

  let cut = str.slice(0, max);
  // Back up to the last whitespace so we don't cut mid-word
  const lastSpace = cut.lastIndexOf(' ');
  if (lastSpace > 0) cut = cut.slice(0, lastSpace);

  // Trim dangling punctuation/whitespace left by the cut
  return cut.replace(/[\s,;:.\-–—]+$/u, '').trimEnd();
}

/**
 * Render social meta tags: Open Graph pairs, Twitter card,
 * canonical link, plain <title>, and meta description.
 */
export function renderMeta({ title, description, url, image, siteName, type } = {}) {
  const desc = truncateDescription(description);
  const card = image ? 'summary_large_image' : 'summary';

  const lines = [];
  lines.push('<meta property="og:title" content="' + escapeAttr(title) + '">');
  lines.push('<meta property="og:description" content="' + escapeAttr(desc) + '">');
  if (url !== undefined) lines.push('<meta property="og:url" content="' + escapeAttr(url) + '">');
  if (image !== undefined) lines.push('<meta property="og:image" content="' + escapeAttr(image) + '">');
  if (siteName !== undefined) lines.push('<meta property="og:site_name" content="' + escapeAttr(siteName) + '">');
  lines.push('<meta property="og:type" content="' + escapeAttr(type ?? 'website') + '">');
  lines.push('<meta name="twitter:card" content="' + card + '">');

  return [
    '<title>' + escapeAttr(title) + '</title>',
    '<meta name="description" content="' + escapeAttr(desc) + '">',
    ...lines,
    '<link rel="canonical" href="' + escapeAttr(url) + '">',
  ].join('\n');
}

/**
 * Parse rendered meta HTML back into the original options object.
 * Inverse of renderMeta for canonical inputs.
 */
export function parseMeta(html) {
  const $ = cheerio.load(html);

  const out = {};
  out.title = $('title').first().text();
  out.description = $('meta[name="description"]').attr('content');

  const og = (name) => $(`meta[property="${name}"]`).attr('content');
  if (og('og:url') !== undefined) out.url = og('og:url');
  if (og('og:image') !== undefined) out.image = og('og:image');
  if (og('og:site_name') !== undefined) out.siteName = og('og:site_name');
  out.type = og('og:type') ?? 'website';

  // Canonical link wins as the authoritative URL if present
  const canonical = $('link[rel="canonical"]').attr('href');
  if (canonical !== undefined && canonical !== '') out.url = canonical;

  return out;
}

