import { describe, it, expect } from 'vitest';
import { renderMeta, parseMeta, truncateDescription } from './meta.js';

const canonicalInput = {
  title: 'My Page Title',
  description: 'A concise description of the page content.',
  url: 'https://example.com/my-page',
  image: 'https://example.com/cover.jpg',
  siteName: 'Example Site',
  type: 'article',
};

describe('round-trip', () => {
  it('parses rendered meta back to the original object', () => {
    const html = renderMeta(canonicalInput);
    expect(parseMeta(html)).toEqual(canonicalInput);
  });

  it('round-trips without optional fields (defaults type=website)', () => {
    const input = {
      title: 'Bare Page',
      description: 'Just the essentials.',
      url: 'https://example.com',
    };
    expect(parseMeta(renderMeta(input))).toEqual(input);
  });
});

describe('truncation', () => {
  const long = 'Discover the finest artisanal coffee beans roasted in small batches every single morning before sunrise. Our master roasters blend rare single-origin varietals from Ethiopia and Colombia into signature house blends.';

  it('caps description at 155 characters', () => {
    expect(long.length).toBeGreaterThan(155);
    const out = truncateDescription(long);
    expect(out.length).toBeLessThanOrEqual(155);
  });

  it('does not cut mid-word', () => {
    const out = truncateDescription(long);
    // The full string must start with the truncated string (prefix property)
    expect(long.startsWith(out)).toBe(true);
    // Next character in the original must be a word boundary
    expect(/\s/.test(long[out.length] ?? ' ')).toBe(true);
  });

  it('leaves no dangling comma or trailing space', () => {
    const out = truncateDescription('One two three, four five six seven eight nine ten eleven twelve thirteen fourteen fifteen sixteen seventeen eighteen nineteen twenty, extra words here');
    expect(out.endsWith(',')).toBe(false);
    expect(out.endsWith(' ')).toBe(false);
    expect(out.length).toBeLessThanOrEqual(155);
  });

  it('returns short descriptions untouched', () => {
    expect(truncateDescription('Short and sweet.')).toBe('Short and sweet.');
  });
});

describe('escaping', () => {
  it('escapes double quotes in title attribute values', () => {
    const html = renderMeta({
      ...canonicalInput,
      title: 'The "Best" Guide',
      description: 'Fine.',
      image: undefined,
    });
    // Raw quote must not appear unescaped inside an attribute
    expect(html).toContain('<title>The &quot;Best&quot; Guide</title>');
    expect(html).toContain('content="The &quot;Best&quot; Guide"');
    expect(html).not.toMatch(/content="[^"]*"[^>]*"/);
  });

  it('escaped quotes survive round-trip', () => {
    const input = { ...canonicalInput, title: 'Quote "Test" Title' };
    expect(parseMeta(renderMeta(input)).title).toBe(input.title);
  });
});

describe('twitter card switching', () => {
  it('uses summary_large_image when an image is present', () => {
    const html = renderMeta({ ...canonicalInput });
    expect(html).toMatch(/<meta name="twitter:card" content="summary_large_image">/);
  });

  it('falls back to summary when no image', () => {
    const { image, ...noImage } = canonicalInput;
    const html = renderMeta(noImage);
    expect(html).toMatch(/<meta name="twitter:card" content="summary">/);
  });
});

